import {$,el,field,read,num,format,action,notice,setupStatus,copy,output,downloads,clearOutputs} from './core.js';
const stop=new Set('a an and are as at be been being by can for from has have if in into is it its of on or our that the their them they this to was we were will with you your'.split(' '));
export function matchText(resume,job){const tokenize=t=>(t.toLowerCase().match(/[a-z][a-z0-9+#.-]*/g)||[]).map(w=>w.replace(/[.-]+$/,'')).filter(w=>w.length>1&&!stop.has(w));const terms=[...new Set(tokenize(job))],present=new Set(tokenize(resume)),matched=terms.filter(t=>present.has(t)),missing=terms.filter(t=>!present.has(t));return {terms,matched,missing,overlap:terms.length?100*matched.length/terms.length:0}}
export async function mount(root,slug){const form=el('div',{class:'fields'});root.append(form);const add=(id,label,type='text',value='',opts={})=>form.append(field(id,label,type,value,opts));const choose=(id,label,options)=>add(id,label,'select',Array.isArray(options[0])?options[0][0]:options[0],{options});const required=id=>{const v=read(id);if(!v)throw Error('Complete '+$('#'+id).labels[0].textContent+'.');return v};const outputText=el('textarea',{id:'writing-result',rows:14,'aria-label':'Editable generated wording'});let generate;
if(slug==='resume-studio'){choose('mode','What are you writing?',['Professional Summary','Career Objective','Experience Bullet']);add('role','Target / current role');add('facts','Relevant experience and skills (your facts)','textarea','',{full:true});add('achievement','What did you do, and what changed?','textarea','',{full:true,hint:'Optional for summaries. For a bullet, include an action and an outcome you can support.'});generate=()=>{const role=required('role'),facts=required('facts'),result=read('achievement');return read('mode')==='Career Objective'?`Seeking a ${role} position where I can apply ${facts.replace(/[.!]$/,'')}. ${result?`I bring experience in ${result.replace(/[.!]$/,'')}.`:''}`.trim():read('mode')==='Experience Bullet'?`${(result||facts).replace(/^[•\-]\s*/,'').replace(/[.!]$/,'')}.`:`${role} with experience in ${facts.replace(/[.!]$/,'')}.${result?' '+result.replace(/[.!]$/,'')+'.':''}`}}
else if(slug==='cover-letter'){add('name','Your name');add('role','Role');add('company','Company');add('recipient','Recipient (optional)');add('facts','Relevant experience and evidence','textarea','',{full:true});add('reason','Why this role or company?','textarea','',{full:true});generate=()=>`Dear ${read('recipient')||'Hiring Team'},\n\nI am applying for the ${required('role')} position at ${required('company')}. ${required('reason').replace(/[.!]$/,'')}.\n\n${required('facts').replace(/[.!]$/,'')}.\n\nI would welcome the opportunity to discuss how my experience fits this role. Thank you for considering my application.\n\nKind regards,\n${required('name')}`}
else if(slug==='linkedin'){choose('mode','Profile section',['Headline','About section','Experience bullets','Carousel outline']);add('role','Role or topic');add('facts','Skills, experience or points to include','textarea','',{full:true,hint:'Enter one fact or point per line.'});add('goal','Professional focus / next step (optional)');generate=()=>{const role=required('role'),facts=required('facts').split('\n').filter(x=>x.trim()),goal=read('goal');switch(read('mode')){case 'Headline':return [role,...facts.slice(0,3)].join(' | ');case 'About section':return `${role}\n\n${facts.join('\n')}\n\n${goal}`.trim();case 'Experience bullets':return facts.map(f=>'• '+f.replace(/^[•-]\s*/, '')).join('\n');default:return `Carousel outline: ${role}\n\nSlide 1 — ${role}\n${facts.map((f,i)=>`Slide ${i+2} — ${f}`).join('\n')}\nSlide ${facts.length+2} — ${goal||'Recap the key points and invite discussion.'}`}}}
else if(slug==='writing'){choose('mode','Message type',['Professional email','Follow-up','Leave request','Resignation','Meeting follow-up','Professional reply']);add('recipient','Recipient');add('subject','Subject');add('name','Your name');add('facts','Facts to communicate','textarea','',{full:true});add('request','Requested action / dates / next step','textarea','',{full:true});generate=()=>{const mode=read('mode'),facts=required('facts'),next=read('request');const opening={'Professional email':'','Follow-up':'I am following up on the matter below.\n\n','Leave request':'I would like to request leave as detailed below.\n\n','Resignation':'Please accept this message as notice of my resignation.\n\n','Meeting follow-up':'Thank you for the discussion. Here are the points and next steps.\n\n','Professional reply':'Thank you for your message.\n\n'}[mode];return `Subject: ${required('subject')}\n\nHello ${required('recipient')},\n\n${opening}${facts}\n\n${next?next+'\n\n':''}Kind regards,\n${required('name')}`}}
else if(slug==='job-match'){add('resume','Resume text','textarea','',{full:true});add('job','Job description','textarea','',{full:true});generate=()=>{const resume=required('resume'),job=required('job'),m=matchText(resume,job);if(!m.terms.length)throw Error('Add a job description with meaningful text.');const observations=[];if(!/experience|employment|work history/i.test(resume))observations.push('An experience heading was not detected.');if(!/education|qualification/i.test(resume))observations.push('An education / qualifications heading was not detected.');if(!/\b\d+(?:\.\d+)?%?\b/.test(resume))observations.push('No numbers were detected. Consider adding relevant outcomes only if you can support them.');return `Keyword overlap: ${format(m.overlap,1)}% (${m.matched.length} of ${m.terms.length} distinct terms)\n\nMatched terms\n${m.matched.join(', ')||'None'}\n\nTerms to review\n${m.missing.join(', ')||'None'}\n\nStructure observations\n${observations.join('\n')||'Basic experience, education and numerical content were detected.'}\n\nThis is literal English keyword overlap, not an employer ATS score or hiring probability. Terms may be generic or irrelevant. Add a term only when it accurately describes your experience.`}}
else if(slug==='invoice'){add('seller','From (name / business)','textarea');add('buyer','Bill to','textarea');add('number','Invoice number','text','INV-001');add('date','Invoice date','date',new Date().toISOString().slice(0,10));add('currency','Currency label','text','INR');add('terms','Payment terms','text','Due within 14 days');add('description','Description','textarea','',{full:true});add('quantity','Quantity','number',1,{min:.001});add('rate','Unit rate','number',1000,{min:0});add('discount','Discount (%)','number',0,{min:0,max:100});add('tax','Tax (%)','number',0,{min:0,max:100});const invoice=el('article',{class:'invoice',hidden:true});root.append(el('div',{class:'actions'},[action('Create invoice',()=>{const q=num('quantity',{min:.001}),r=num('rate',{min:0}),d=num('discount',{min:0,max:100})/100,t=num('tax',{min:0,max:100})/100,sub=q*r,discount=sub*d,net=sub-discount,total=net*(1+t),money=v=>`${read('currency')} ${format(v)}`;if(!Number.isFinite(total))throw Error('Amounts are too large.');invoice.replaceChildren();invoice.hidden=false;invoice.append(el('header',{},[el('div',{},[el('h2',{text:'INVOICE'}),el('p',{text:`${required('number')} · ${required('date')}`})]),el('pre',{text:required('seller')})]),el('h3',{text:'Bill to'}),el('pre',{text:required('buyer')}));const table=el('table');table.append(el('thead',{},el('tr',{},['Description','Quantity','Rate','Amount'].map(s=>el('th',{text:s})))),el('tbody',{},el('tr',{},[required('description'),format(q),money(r),money(sub)].map(s=>el('td',{text:s})))));invoice.append(table,el('p',{text:`Discount: ${money(discount)}\nTax: ${money(net*t)}`}),el('h3',{text:`Total due: ${money(total)}`}),el('p',{text:read('terms')}));document.body.classList.add('print-invoice')},true),action('Print / Save PDF',()=>{if(invoice.hidden)throw Error('Create the invoice first.');window.print()})]),invoice);notice(root,'Simple single-line invoice. Discount is applied before tax. Check your local invoice requirements before issuing it. Choose “Save as PDF” in your device’s print options.');setupStatus(root);return}
notice(root,slug==='job-match'?'Local, deterministic text comparison. This does not reproduce an employer’s ATS or predict interviews.':'Structured wording based on the facts you enter. Review and edit the result before using it; no experience or achievements are invented.');root.append(el('div',{class:'actions'},[action(slug==='job-match'?'Analyze match':'Create wording',()=>{outputText.value=generate()},true),action('Copy',()=>copy(outputText.value)),action('Download TXT',()=>{if(!outputText.value)throw Error('Generate or enter wording first.');clearOutputs();output(new Blob([outputText.value],{type:'text/plain;charset=utf-8'}),slug+'.txt')})]),outputText);setupStatus(root);downloads(root)}
